const items = $input.all();

return [
  {
    json: {
      news: items.map(item => item.json.output)
    }
  }
];

const text = $input.first().json.text;

const lines = text
  .replace(/\\n/g, '\n')
  .split('\n')
  .map(line => line.trim())
  .filter(line => line !== '');

let html = `
<div style="font-family: Arial, sans-serif; max-width: 900px; margin: 0 auto; color: #222; line-height: 1.5;">
  <h1 style="font-size: 24px; margin-bottom: 8px;">
    📊 Investment Intelligence Digest
  </h1>
  <div style="color:#666; margin-bottom:20px;">
    Daily portfolio intelligence
  </div>
`;

let inList = false;

for (const line of lines) {

  // Stock heading: 📌 MBB
  if (/^📌\s*\*\*.*\*\*$/.test(line)) {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    const ticker = line
      .replace(/^📌\s*/, '')
      .replace(/\*\*/g, '');

    html += `
      <div style="margin-top:28px; padding-bottom:8px; border-bottom:2px solid #ddd;">
        <h2 style="font-size:20px; margin:0;">
          📌 ${ticker}
        </h2>
      </div>
    `;

  // Section headings
  } else if (/^🎯\s*\*\*.*\*\*$/.test(line)) {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    const title = line
      .replace(/^🎯\s*/, '')
      .replace(/\*\*/g, '');

    html += `
      <h3 style="margin:18px 0 6px; font-size:16px;">
        🎯 ${title}
      </h3>
    `;

  } else if (/^🟢\s*\*\*.*\*\*$/.test(line)) {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    const title = line
      .replace(/^🟢\s*/, '')
      .replace(/\*\*/g, '');

    html += `
      <h3 style="margin:18px 0 6px; font-size:16px;">
        🟢 ${title}
      </h3>
    `;

  } else if (/^🔴\s*\*\*.*\*\*$/.test(line)) {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    const title = line
      .replace(/^🔴\s*/, '')
      .replace(/\*\*/g, '');

    html += `
      <h3 style="margin:18px 0 6px; font-size:16px;">
        🔴 ${title}
      </h3>
    `;

  } else if (/^👀\s*\*\*.*\*\*$/.test(line)) {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    const title = line
      .replace(/^👀\s*/, '')
      .replace(/\*\*/g, '');

    html += `
      <h3 style="margin:18px 0 6px; font-size:16px;">
        👀 ${title}
      </h3>
    `;

  } else if (/^📌\s*\*\*Investment Thesis\*\*/.test(line)) {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    html += `
      <h3 style="margin:18px 0 6px; font-size:16px;">
        📌 Investment Thesis
      </h3>
    `;

  } else if (/^💡\s*\*\*.*\*\*$/.test(line)) {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    const title = line
      .replace(/^💡\s*/, '')
      .replace(/\*\*/g, '');

    html += `
      <h3 style="margin:18px 0 6px; font-size:16px;">
        💡 ${title}
      </h3>
    `;

  // Bullet
  } else if (/^[-•]\s*/.test(line)) {

    if (!inList) {
      html += `
        <ul style="margin-top:4px; padding-left:22px;">
      `;
      inList = true;
    }

    const content = line
      .replace(/^[-•]\s*/, '')
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    html += `<li style="margin-bottom:5px;">${content}</li>`;

  // Normal paragraph
  } else {
    if (inList) {
      html += '</ul>';
      inList = false;
    }

    const content = line
      .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    html += `
      <p style="margin:6px 0 10px;">
        ${content}
      </p>
    `;
  }
}

if (inList) {
  html += '</ul>';
}

html += `
  <div style="margin-top:30px; padding-top:12px; border-top:1px solid #ddd; color:#888; font-size:12px;">
    This email was generated automatically with n8n.
  </div>
</div>
`;

return [
  {
    json: {
      html
    }
  }
];
